import{_ as d,o as e,c as o,a2 as r}from"./chunks/framework.CCCdsIgc.js";const u=JSON.parse('{"title":"三种模式与工作区","description":"","frontmatter":{},"headers":[],"relativePath":"guide/usage.md","filePath":"guide/usage.md"}'),a={name:"guide/usage.md"};function c(l,t,i,n,s,h){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="三种模式与工作区" tabindex="-1">三种模式与工作区 <a class="header-anchor" href="#三种模式与工作区" aria-label="Permalink to &quot;三种模式与工作区&quot;">​</a></h1><h2 id="打开窗口" tabindex="-1">打开窗口 <a class="header-anchor" href="#打开窗口" aria-label="Permalink to &quot;打开窗口&quot;">​</a></h2><ul><li>点桌面上的<strong>悬浮球</strong>，或按 <code>Ctrl + Alt + Space</code>；</li><li>悬浮球可以拖到任何位置，<strong>把文件拖到球上</strong>就直接发给 AI；</li><li>右键悬浮球有更多功能：对话浮窗、划词翻译、截图提问等。</li></ul><h2 id="三种模式" tabindex="-1">三种模式 <a class="header-anchor" href="#三种模式" aria-label="Permalink to &quot;三种模式&quot;">​</a></h2><p>输入框左下角切换：</p><table tabindex="0"><thead><tr><th>模式</th><th>适合</th><th>会不会动你的电脑</th></tr></thead><tbody><tr><td><strong>办事</strong></td><td>整理文件、汇总表格、写文档、执行命令</td><td>会，按<a href="./safety.html">确认规则</a>来</td></tr><tr><td><strong>对话</strong></td><td>问问题、写东西、出主意</td><td>不会</td></tr><tr><td><strong>翻译</strong></td><td>文字或整份文件翻译</td><td>不会</td></tr></tbody></table><h2 id="工作区" tabindex="-1">工作区 <a class="header-anchor" href="#工作区" aria-label="Permalink to &quot;工作区&quot;">​</a></h2><p>办事模式下，输入框下方能选<strong>工作区</strong>（一个文件夹）。</p><ul><li>AI 生成的文件都放在工作区里；</li><li>默认权限「工作区内修改」下，AI 只能改工作区里面的东西，改外面的要问你；</li><li>在资源管理器里右键文件夹「在这里用 FlyknitBuddy 办事」，可以直接以这个文件夹为工作区开新任务。</li></ul><h2 id="权限" tabindex="-1">权限 <a class="header-anchor" href="#权限" aria-label="Permalink to &quot;权限&quot;">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>说明</th></tr></thead><tbody><tr><td>仅可查看</td><td>只能看、只能查，不能改任何东西</td></tr><tr><td>工作区内修改（默认）</td><td>只能在工作区里新建、修改文件；命令按规则确认</td></tr><tr><td>完全权限</td><td>可以改工作区外的文件，普通命令不再确认；危险命令仍然拦截。只对当前这个任务有效，IT 也可以关掉这一档</td></tr></tbody></table><h2 id="好用的小功能" tabindex="-1">好用的小功能 <a class="header-anchor" href="#好用的小功能" aria-label="Permalink to &quot;好用的小功能&quot;">​</a></h2><ul><li><strong>增强提示词</strong>：输入框里点 ✨，把随手写的一句话改写得更清楚，不满意点 ↺ 恢复；</li><li><strong>斜杠命令和快捷指令</strong>：输入框里打 <code>/</code> 列出全部命令，方向键选、回车执行（见下面的表）；IT 和你自己加的快捷指令也在里面，比如 <code>/周报</code>；</li><li><strong>先出方案</strong>：点「先出方案」，AI 只调研、写出打算怎么做，你看过再点「按方案执行」；</li><li><strong>运行中插话</strong>：AI 还在做的时候可以继续打字补充要求，不用等它做完；</li><li><strong>顺便问一句</strong>：<code>Ctrl + ;</code> 问一个和当前任务有关的小问题，不打断正在跑的任务；</li><li><strong>从这里分叉</strong>：任意一条回答下点分叉按钮，另开一个对话试别的方向，原对话不受影响。</li></ul><h2 id="斜杠命令" tabindex="-1">斜杠命令 <a class="header-anchor" href="#斜杠命令" aria-label="Permalink to &quot;斜杠命令&quot;">​</a></h2><p>在输入框里打 <code>/</code> 就会列出来。这些命令在电脑上直接办，<strong>不发给 AI、不占额度</strong>（<code>/compact</code>、<code>/init</code> 除外），和点界面上对应的按钮效果完全一样，IT 的限制照样生效。</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/help</code></td><td>列出全部命令</td></tr><tr><td><code>/compact 要保留的内容</code></td><td>马上整理对话，比如 <code>/compact 保留报价和交期</code>；后面不写就照常整理</td></tr><tr><td><code>/permission 仅可查看 | 工作区内修改 | 完全权限</code></td><td>调这个对话的权限；选「完全权限」照样会先弹确认</td></tr><tr><td><code>/model 模型名</code></td><td>换模型；只打 <code>/model</code> 列出能选的，<code>/model auto</code> 交给系统选</td></tr><tr><td><code>/plan</code></td><td>打开 / 关闭「先出方案」</td></tr><tr><td><code>/new</code>（<code>/clear</code>）</td><td>开一个新对话</td></tr><tr><td><code>/context</code></td><td>看上下文用了多少</td></tr><tr><td><code>/usage</code></td><td>看今天的额度</td></tr><tr><td><code>/rewind</code></td><td>打开上一轮改动的文件，看过再决定还不还原</td></tr><tr><td><code>/fork</code></td><td>从最新的回答分出一个新对话</td></tr><tr><td><code>/memory</code></td><td>管理记忆</td></tr><tr><td><code>/status</code></td><td>这个对话正在用的模式、模型、权限、工作区、额度一览</td></tr><tr><td><code>/btw 问题</code></td><td>顺便问一句，不打断任务</td></tr><tr><td><code>/init</code></td><td>开了开发者工具时：生成项目说明 FLYKNIT.md</td></tr><tr><td><code>/review 重点看什么</code></td><td>开了开发者工具时：审查还没提交的改动，AI 只看不改，列出问题清单</td></tr><tr><td><code>/mcp</code></td><td>打开连接器页：看连接状态、重新连接</td></tr><tr><td><code>/export</code></td><td>把这个对话导出成 Markdown，放进这个对话的工作区（不会覆盖已有文件）</td></tr><tr><td><code>/doctor</code></td><td>打开网络诊断</td></tr><tr><td><code>/feedback</code>（<code>/bug</code>）</td><td>意见反馈，自动带上这个对话的标题和编号</td></tr><tr><td><code>/long</code></td><td>打开 / 关闭长任务模式</td></tr><tr><td><code>/sandbox</code></td><td>开了沙箱任务时：打开 / 关闭沙箱（关的时候照样先确认）</td></tr></tbody></table><p>快捷指令和这些命令重名时，以命令为准。</p>',17)])])}const b=d(a,[["render",c]]);export{u as __pageData,b as default};
